/*
 * Reclassifies the code tokens generated by Pandoc (Skylighting) to approximate GitHub's colors.
 * Used by print-pdf.mjs before printing; the actual colors live in github-pdf.css.
 * Added classes: cl = call/constant (blue), fn = definition (purple), pm = macro parameter (orange).
 */
(function (root) {
  'use strict';

  var LANG = {
    cpp: 'cpp', 'c++': 'cpp', cxx: 'cpp', cc: 'cpp', c: 'cpp', h: 'cpp', hpp: 'cpp', ino: 'cpp', arduino: 'cpp',
    json: 'json', jsonc: 'json', yaml: 'yaml', yml: 'yaml', cmake: 'cmake', ini: 'ini', properties: 'properties',
    bash: 'bash', sh: 'bash', shell: 'bash', zsh: 'bash'
  };
  var PRIM = set('int bool void char short long float double unsigned signed auto');
  var LIT = set('true false nullptr NULL');
  var KW = set('static_cast dynamic_cast reinterpret_cast const_cast sizeof new delete return template typename using ' +
    'namespace struct class enum union public private protected virtual override static inline constexpr volatile ' +
    'extern explicit const typedef if else for while do switch case break continue goto default try catch throw operator');
  var CALLISH = set('return else case throw new delete sizeof do goto');
  var DECL = set('class struct enum namespace typename');

  function set(s) { var o = {}; s.split(' ').forEach(function (w) { o[w] = true; }); return o; }
  function esc(s) { return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }

  function langOf(pre) {
    var lists = [pre.classList];
    var code = pre.querySelector('code');
    if (code) lists.push(code.classList);
    for (var i = 0; i < lists.length; i++) {
      for (var j = 0; j < lists[i].length; j++) {
        var l = LANG[lists[i][j].toLowerCase()];
        if (l) return l;
      }
    }
    return '';
  }

  function run(doc) {
    var mk = function (cls, text) { var s = doc.createElement('span'); s.className = cls; s.textContent = text; return s; };

    // ---------- C / C++ ----------
    function tokenizeText(node, lineText, offset, mode) {
      var text = node.nodeValue;
      var re = /[A-Za-z_]\w*(?:::[A-Za-z_]\w*)*|\d+(?:\.\d+)?/g;
      var frag = doc.createDocumentFragment(), last = 0, m;
      var endsSemi = /;\s*$/.test(lineText.replace(/\/\/.*$|\/\*.*?\*\//g, '').replace(/\s+$/, ''));
      while ((m = re.exec(text))) {
        var id = m[0], start = offset + m.index, prefix = lineText.slice(0, start);
        var after = lineText.slice(start + id.length), cls = '';
        var tail = id.split('::').pop();
        var prevWord = (/([A-Za-z_]\w*)\s*$/.exec(prefix) || [])[1] || '';
        if (/^\d/.test(id)) cls = 'dv';
        else if (LIT[id]) cls = 'dv';
        else if (PRIM[id] || KW[id]) cls = 'kw';
        else if (/^[A-Z][A-Z0-9_]+$/.test(tail)) cls = 'cl';
        else if (/_t$/.test(tail)) cls = 'dt';
        else if (mode === 'code') {
          if (DECL[prevWord]) cls = 'fn';
          else if (/^\s*\(/.test(after)) {
            var p = prefix.replace(/\s+$/, '');
            if (/(\.|->)$/.test(p) || CALLISH[prevWord]) cls = 'cl';
            else if (p === '') cls = endsSemi ? 'cl' : 'fn';
            else if (/[\w*&>\]]$/.test(p) && /\s$/.test(prefix)) cls = 'fn';
          }
        }
        if (cls) {
          if (m.index > last) frag.appendChild(doc.createTextNode(text.slice(last, m.index)));
          frag.appendChild(mk(cls, id));
          last = m.index + id.length;
        }
      }
      if (last === 0) return;
      if (last < text.length) frag.appendChild(doc.createTextNode(text.slice(last)));
      node.parentNode.replaceChild(frag, node);
    }

    function fixCppLine(line) {
      var i, n;
      // a::b  ->  a single text token
      Array.prototype.slice.call(line.childNodes).forEach(function (c) {
        if (c.nodeType === 1 && c.className === 'op' && c.textContent === '::') c.parentNode.replaceChild(doc.createTextNode('::'), c);
      });
      line.normalize();

      // preprocessor directives
      var defineLine = false;
      Array.prototype.slice.call(line.childNodes).forEach(function (c) {
        if (c.nodeType === 1 && c.className === 'pp') {
          var m = /^(#\s*)([A-Za-z]+)([\s\S]*)$/.exec(c.textContent);
          if (!m) { if (!c.textContent.trim()) c.parentNode.replaceChild(doc.createTextNode(c.textContent), c); return; }
          var f = doc.createDocumentFragment();
          f.appendChild(doc.createTextNode(m[1]));   // the hash sign keeps the default color
          f.appendChild(mk('pp', m[2]));
          var rest = m[3];
          if (m[2] === 'define') {
            defineLine = true;
            var d = /^(\s*)([A-Za-z_]\w*)([\s\S]*)$/.exec(rest);
            if (d) {
              f.appendChild(doc.createTextNode(d[1]));
              f.appendChild(mk('fn', d[2]));
              if (d[3]) f.appendChild(doc.createTextNode(d[3]));
            } else if (rest) f.appendChild(doc.createTextNode(rest));
          } else if (rest) {
            f.appendChild(mk('nt', rest));   // rest of the directive: no coloring
          }
          c.parentNode.replaceChild(f, c);
        }
      });
      line.normalize();

      // access specifiers: the colon is red as well
      var kids = Array.prototype.slice.call(line.childNodes);
      kids.forEach(function (c, k) {
        if (c.nodeType !== 1) return;
        var t = c.textContent;
        if (c.className === 'dt' && PRIM[t]) c.className = 'kw';
        else if (c.className === 'kw' && LIT[t]) c.className = 'dv';
        else if (c.className === 'kw' && /^(public|private|protected)$/.test(t)) {
          var nx = kids[k + 1];
          if (nx && nx.nodeType === 1 && nx.className === 'op' && nx.textContent.charAt(0) === ':') nx.className = 'kw';
        }
      });

      // plain text: identifiers and numbers
      var lineText = line.textContent, offset = 0;
      var nodes = Array.prototype.slice.call(line.childNodes);
      nodes.forEach(function (c, k) {
        var len = c.textContent.length;
        if (c.nodeType === 3) {
          var prev = nodes[k - 1], next = nodes[k + 1];
          var inParams = defineLine && prev && prev.nodeType === 1 && prev.className === 'op' && /\($/.test(prev.textContent) &&
            prev.textContent !== '()' && next && next.nodeType === 1 && next.className === 'op' && /^\)/.test(next.textContent);
          if (inParams && c.nodeValue.trim()) {
            c.parentNode.replaceChild(mk('pm', c.nodeValue), c);
          } else {
            tokenizeText(c, lineText, offset, defineLine ? 'macro' : 'code');
          }
        }
        offset += len;
      });
    }

    // ---------- CMake: uppercase arguments as strings ----------
    function fixCmakeLine(line) {
      Array.prototype.slice.call(line.childNodes).forEach(function (c) {
        if (c.nodeType !== 3) return;
        var re = /\b[A-Z][A-Z0-9_]{2,}\b/g, text = c.nodeValue, last = 0, m, frag = doc.createDocumentFragment();
        while ((m = re.exec(text))) {
          if (m.index > last) frag.appendChild(doc.createTextNode(text.slice(last, m.index)));
          frag.appendChild(mk('st', m[0]));
          last = m.index + m[0].length;
        }
        if (!last) return;
        if (last < text.length) frag.appendChild(doc.createTextNode(text.slice(last)));
        c.parentNode.replaceChild(frag, c);
      });
    }

    // ---------- .properties files (not colored by Pandoc) ----------
    function fixProperties(code) {
      var out = code.textContent.replace(/\n$/, '').split('\n').map(function (l) {
        var m = /^(\s*)([^=:#!\s][^=:]*?)(\s*[=:])([\s\S]*)$/.exec(l);
        if (/^\s*[#!]/.test(l)) return '<span class="co">' + esc(l) + '</span>';
        if (m) return esc(m[1]) + '<span class="kw">' + esc(m[2] + m[3]) + '</span>' + esc(m[4]);
        return esc(l);
      });
      code.innerHTML = out.join('\n') + '\n';
    }

    Array.prototype.slice.call(doc.querySelectorAll('section.doc pre, pre')).forEach(function (pre) {
      if (pre.getAttribute('data-lang')) return;
      var lang = langOf(pre);
      if (!lang) return;
      pre.setAttribute('data-lang', lang);
      var code = pre.querySelector('code');
      if (!code) return;
      if (lang === 'properties') { fixProperties(code); return; }
      var lines = Array.prototype.slice.call(code.children).filter(function (e) { return e.tagName === 'SPAN'; });
      if (lang === 'cpp') lines.forEach(fixCppLine);
      else if (lang === 'cmake') lines.forEach(fixCmakeLine);
    });
  }

  root.githubCodeColors = run;
  if (typeof module !== 'undefined') module.exports = run;
})(typeof window !== 'undefined' ? window : globalThis);
